"""Demo: Verifying the Hamming ball-size formula |B_d(r)| = sum_{k<=d} C(N,k)."""
from itertools import product
from math import comb
from typing import Tuple

def hamming(a: Tuple[int, ...], b: Tuple[int, ...]) -> int:
    return sum(1 for x, y in zip(a, b) if x != y)

def ball_size_formula(N: int, d: int) -> int:
    return sum(comb(N, k) for k in range(d + 1))

def ball_size_bruteforce(N: int, d: int, center: Tuple[int, ...]) -> int:
    return sum(1 for t in product((0, 1), repeat=N) if hamming(center, t) <= d)

def main() -> None:
    N = 6
    for center in [tuple([0]*N), tuple([1]*N)]:
        for d in range(N + 1):
            f = ball_size_formula(N, d)
            b = ball_size_bruteforce(N, d, center)
            assert f == b, (center, d, f, b)
            print(f"center={center} d={d}: formula={f} bruteforce={b}")
    print("All centers and radii agree with sum_{k<=d} C(N,k).")

if __name__ == "__main__":
    main()

"""Demo: The accuracy barrier -- a family below the covering threshold is defeated."""
from itertools import product
from math import comb
from typing import List, Optional, Tuple

def hamming(a: Tuple[int, ...], b: Tuple[int, ...]) -> int:
    return sum(1 for x, y in zip(a, b) if x != y)

def ball_size_formula(N: int, d: int) -> int:
    return sum(comb(N, k) for k in range(d + 1))

def find_uncovered(N: int, d: int, family: List[Tuple[int, ...]]) -> Optional[Tuple[int, ...]]:
    for t in product((0, 1), repeat=N):
        if all(hamming(r, t) > d for r in family):
            return t
    return None

def main() -> None:
    N, d = 6, 1
    ball = ball_size_formula(N, d)
    max_family = (2 ** N) // ball  # strictly below covering threshold
    strings = list(product((0, 1), repeat=N))
    family = strings[:max_family]
    assert len(family) * ball < 2 ** N
    t = find_uncovered(N, d, family)
    print(f"N={N} d={d} ballsize={ball} |F|={len(family)}")
    print(f"|F|*ball={len(family)*ball} < 2^N={2**N}")
    print(f"uncovered truth pattern: {t}")
    print(f"min errors over F: {min(hamming(r, t) for r in family)} (> d={d})")

if __name__ == "__main__":
    main()

"""Demo: The diagonal (Cantor) construction defeats any enumeration of oracles."""
from typing import Callable

Oracle = Callable[[int], bool]

def diagonal(enum: Callable[[int], Oracle]) -> Oracle:
    return lambda n: not enum(n)(n)

def main() -> None:
    # enum(k)(n) = bit k of n
    def enum(k: int) -> Oracle:
        return lambda n: bool((n >> k) & 1)
    D = diagonal(enum)
    for k in range(10):
        assert D(k) != enum(k)(k)
        print(f"input {k}: D={int(D(k))} enum(k)(k)={int(enum(k)(k))} disagree=True")
    print("D differs from every listed oracle -> not in the enumeration.")

if __name__ == "__main__":
    main()

