    return function(n):
        return NOT enum(n)(n)

function VERIFY_ESCAPES(enum, checks):
    D <- DIAGONAL_ORACLE(enum)
    for n = 0 .. checks-1:
        assert D(n) != enum(n)(n)
    return true

