from typing import Callable

Oracle = Callable[[int], bool]

def diagonal_oracle(enum: Callable[[int], Oracle]) -> Oracle:
    """Given an enumeration `enum` of oracles, return the diagonal oracle D with
    D(n) = not enum(n)(n).  D provably differs from enum(n) at input n, so D is
    outside the range of enum: a witness to non-enumerability."""
    return lambda n: not enum(n)(n)

def verify_escapes(enum: Callable[[int], Oracle], checks: int) -> bool:
    """Confirm on `checks` inputs that the diagonal oracle disagrees with the
    corresponding listed oracle."""
    D = diagonal_oracle(enum)
    return all(D(n) != enum(n)(n) for n in range(checks))

